--
-- Table structure for table `job_card_services`
--

DROP TABLE IF EXISTS `job_card_services`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_card_services` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_card_id` int NOT NULL,
  `concern_id` int unsigned DEFAULT NULL,
  `service_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `item_type` enum('part','labour') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'labour',
  `part_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `part_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `labour_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `price_type` enum('price','mrp','fixed','variable') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'price',
  `qty` decimal(10,2) DEFAULT '1.00',
  `rate` decimal(10,2) DEFAULT NULL,
  `discount_pct` decimal(5,2) DEFAULT '0.00',
  `hsn_sac` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tax_pct` decimal(5,2) DEFAULT '18.00',
  `tax_amount` decimal(10,2) DEFAULT '0.00',
  `is_selected` tinyint(1) DEFAULT '1',
  `sort_order` int DEFAULT '0',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'pc',
  `job_category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `package_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `old_part` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_jcs_job_card` (`job_card_id`),
  KEY `idx_jcs_job` (`job_card_id`),
  KEY `fk_jcs_concern` (`concern_id`),
  CONSTRAINT `fk_jcs_concern` FOREIGN KEY (`concern_id`) REFERENCES `customer_concerns` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_card_services_ibfk_1` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

